// Physician Assistant - Medical Case Challenge Practice Test 6. Original questions written for Valus from the
// HOSA 2026–27 test plan, slightly harder than the sample items: short clinical cases across body systems,
// assessment and diagnostic reasoning not covered in Practice Tests 1–5.
import {q, mix} from './q.js';
const CMDT='Papadakis et al., Current Medical Diagnosis & Treatment', MP='MedlinePlus';
const DP='Disease Process & Terminology (includes cancer & neoplasms)', INTEG='Integumentary', MSK='Musculoskeletal', CIRC='Circulatory & Lymphatic', RESP='Respiratory', DIG='Digestive', ENDO='Endocrine', NERV='Nervous & Senses', REPRO='Reproductive', URIN='Urinary', MENT='Mental Disorders', ASSESS='Patient Assessment', DX='Diagnosis';

export default {
 id:'physician-assistant-6',
 event:'Physician Assistant - Medical Case Challenge',
 title:'Practice Test 6',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Current Medical Diagnosis & Treatment (CMDT) and MedlinePlus',
 plan:[{area:DP,weight:10},{area:INTEG,weight:4},{area:MSK,weight:6},{area:CIRC,weight:10},{area:RESP,weight:6},{area:DIG,weight:10},{area:ENDO,weight:6},{area:NERV,weight:8},{area:REPRO,weight:4},{area:URIN,weight:4},{area:MENT,weight:6},{area:ASSESS,weight:12},{area:DX,weight:14}],
 questions:mix([
  q(DP,'After weeks in a cast, a patient’s calf muscles have become smaller. What is this change called?','Atrophy',['Hypertrophy','Hyperplasia','Dysplasia, a disordered growth of cells that can become cancer'],'A','Atrophy is a decrease in cell size or number, often from disuse, poor blood supply or aging.',CMDT),
  q(DP,'How does a sign differ from a symptom?','A sign can be observed or measured, while a symptom is reported by the patient',['They mean exactly the same thing','A symptom is always measured with a device','A sign is anything the patient feels but no one else can detect'],'B','Fever on a thermometer is a sign, while a headache the patient describes is a symptom.',CMDT),
  q(DP,'How does tumor grade differ from tumor stage?','Grade describes how abnormal the cells look; stage describes how far the cancer has spread',['They are the same measure','Grade describes the size only','Stage describes how abnormal the cells look under the microscope'],'C','A high-grade tumor has very abnormal cells and tends to grow faster.',CMDT),
  q(DP,'A heart defect is present at birth. What term describes it?','Congenital',['Acquired','Idiopathic','Iatrogenic, caused by medical treatment after birth'],'D','Congenital conditions are present at birth and may be genetic or caused by events during pregnancy.',CMDT),
  q(DP,'A patient has a soft, movable, painless lump under the skin made of fat cells. What is it most likely?','Lipoma',['Liposarcoma','Lymphoma','Melanoma that has spread under the skin'],'A','Lipomas are common benign tumors and are removed only if they cause problems.',CMDT),
  q(INTEG,'A patient develops raised, itchy welts that come and go within hours after eating shellfish. What is this?','Urticaria (hives)',['Psoriasis','Eczema','Cellulitis, a spreading bacterial skin infection'],'B','Hives are usually caused by histamine release and are treated with antihistamines.',MP),
  q(INTEG,'A middle-aged adult has facial redness with flushing, small bumps and visible blood vessels on the cheeks and nose. What is likely?','Rosacea',['Acne vulgaris','Lupus','Seborrheic keratosis, a stuck-on brown growth'],'C','Triggers include heat, alcohol and spicy foods, and unlike acne there are usually no blackheads.',MP),
  q(MSK,'A 13-year-old athlete has a painful bump just below the kneecap that hurts with running and jumping. What is likely?','Osgood-Schlatter disease',['ACL tear','Patellar dislocation','Osteosarcoma, a bone cancer that often appears near the knee'],'D','Repeated pulling of the patellar tendon irritates the growth area of the tibia during growth spurts.',MP),
  q(MSK,'After an ankle injury, a patient cannot bear weight and has tenderness at the back edge of the lateral malleolus. What do the Ottawa rules suggest?','An ankle X-ray is needed',['No imaging is needed','An MRI of the knee','Immediate surgery without imaging'],'A','The Ottawa ankle rules help decide which ankle injuries need X-rays to look for fractures.',MP),
  q(MSK,'An overweight 12-year-old has a limp and knee pain, and the hip has limited internal rotation. What should be suspected?','Slipped capital femoral epiphysis',['Osgood-Schlatter disease','Growing pains','A simple knee sprain from sports'],'B','Hip problems often cause pain felt in the knee, so the hip must be examined in a limping child.',MP),
  q(CIRC,'A young adult has episodes of rapid heartbeat, and the ECG shows a short PR interval with a slurred upstroke of the QRS. What is likely?','Wolff-Parkinson-White syndrome',['Complete heart block','Hyperkalemia','First-degree heart block with a long PR interval'],'C','An extra electrical pathway causes the delta wave and can lead to fast heart rhythms.',CMDT),
  q(CIRC,'A man develops dark urine and jaundice after eating fava beans. Which enzyme deficiency is likely?','G6PD deficiency',['Iron deficiency','Vitamin B12 deficiency','Pyruvate kinase excess'],'D','Without G6PD, red cells are damaged by oxidant stress from certain foods, drugs and infections.',CMDT),
  q(CIRC,'Weeks after untreated strep throat, a child has fever, joint pain and a new heart murmur. What is suspected?','Acute rheumatic fever',['Kawasaki disease','Infective endocarditis from drug use','Lyme carditis from a tick bite'],'A','Rheumatic fever can damage heart valves, which is why strep throat is treated with antibiotics.',CMDT),
  q(CIRC,'After a viral illness, a young adult has chest pain, shortness of breath and a high troponin with normal coronary arteries. What is likely?','Myocarditis',['Stable angina','Aortic dissection','A blocked coronary artery'],'B','Myocarditis is inflammation of the heart muscle and can cause heart failure or arrhythmias.',CMDT),
  q(CIRC,'An ECG shows regular “sawtooth” flutter waves at about 300 per minute. What rhythm is this?','Atrial flutter',['Atrial fibrillation','Ventricular fibrillation','Sinus rhythm with premature beats'],'C','Atrial flutter often conducts 2:1, giving a ventricular rate near 150 beats per minute.',CMDT),
  q(RESP,'A retired shipyard worker has chest pain, shortness of breath and a pleural mass. Which cancer is linked to his asbestos exposure?','Mesothelioma',['Small cell lung cancer only','Lymphoma','Laryngeal cancer from voice strain'],'D','Mesothelioma can appear decades after asbestos exposure and affects the lining of the lungs.',CMDT),
  q(RESP,'A patient who had a seizure develops fever and cough. In which part of the lung is aspiration pneumonia most likely when the patient was upright?','The right lower lobe',['The left upper lobe','The right middle lobe only','The apex of the left lung'],'A','The right main bronchus is wider and more vertical, so inhaled material usually goes to the right side.',CMDT),
  q(RESP,'An adult has sudden fever, muscle aches and cough during flu season. When does oseltamivir work best?','When started within 48 hours of symptom onset',['Only after 2 weeks of illness','Only if the patient has pneumonia','When given with antibiotics for every patient'],'B','Early antiviral treatment shortens illness and is recommended for high-risk patients.',MP),
  q(DIG,'An older adult has painless jaundice, weight loss and a palpable, non-tender gallbladder. What is suspected?','Pancreatic cancer (head of the pancreas)',['Gallstones','Hepatitis A','Peptic ulcer disease'],'C','A tumor blocking the bile duct causes jaundice; a non-tender enlarged gallbladder is Courvoisier’s sign.',CMDT),
  q(DIG,'A healthy young adult has mild yellowing of the eyes only when fasting or sick. Indirect bilirubin is slightly high, and other tests are normal. What is likely?','Gilbert syndrome',['Hepatitis C','Cirrhosis','Biliary obstruction from a gallstone in the common bile duct'],'D','Gilbert syndrome is a harmless inherited condition with reduced bilirubin processing.',CMDT),
  q(DIG,'A patient with long-standing diabetes feels full after a few bites and vomits undigested food hours after meals. What is likely?','Gastroparesis',['Appendicitis','Peptic ulcer perforation','Gallbladder cancer'],'A','Damage to the vagus nerve slows stomach emptying, and small, low-fat meals help.',CMDT),
  q(DIG,'A patient has sharp, tearing pain during bowel movements with a small amount of bright red blood. What is likely?','Anal fissure',['Internal hemorrhoids','Colon cancer','Diverticulosis, which causes painless bleeding'],'B','Anal fissures are small tears in the anal lining, often after passing hard stools.',MP),
  q(DIG,'Which bloodborne viral hepatitis most often becomes chronic and can now usually be cured with oral antiviral drugs?','Hepatitis C',['Hepatitis A','Hepatitis E','Hepatitis B, which can be controlled but rarely cured'],'C','Screening adults for hepatitis C is recommended because many people have no symptoms.',CMDT),
  q(ENDO,'A woman has hypothyroidism and positive anti-thyroid peroxidase (anti-TPO) antibodies. What is the likely cause?','Hashimoto thyroiditis',['Graves disease','Thyroid cancer','Iodine excess from seafood'],'D','Hashimoto thyroiditis is an autoimmune disease and is the most common cause of hypothyroidism in the U.S.',CMDT),
  q(ENDO,'Why is a monofilament test done during a diabetic foot exam?','To check for loss of protective sensation from neuropathy',['To measure blood sugar','To test for infection','To check the pulse in the foot'],'A','Patients who cannot feel the monofilament are at high risk for unnoticed foot ulcers.',CMDT),
  q(ENDO,'A patient has a large waist, high triglycerides, low HDL, high blood pressure and high fasting glucose. What is this cluster called?','Metabolic syndrome',['Cushing syndrome','Addison disease','Type 1 diabetes'],'B','Metabolic syndrome raises the risk of heart disease and type 2 diabetes.',CMDT),
  q(NERV,'A patient has muscle weakness with both twitching and atrophy, plus brisk reflexes, but normal sensation. What is likely?','Amyotrophic lateral sclerosis (ALS)',['Multiple sclerosis','Guillain-Barré syndrome','Myasthenia gravis, which worsens with repeated use'],'C','ALS damages both upper and lower motor neurons and progresses over time.',CMDT),
  q(NERV,'A patient with back pain has numbness in the groin and inner thighs and new trouble controlling urine. What is suspected?','Cauda equina syndrome',['Simple muscle strain','Sciatica only','Kidney stone'],'D','Saddle anesthesia and bladder problems are an emergency that needs urgent MRI and surgery.',CMDT),
  q(NERV,'A toddler with ear pain and fever has a red, bulging eardrum. What is the likely diagnosis?','Acute otitis media',['Otitis externa','Earwax buildup','A foreign body in the ear canal'],'A','Middle ear infections often follow colds, and some resolve without antibiotics.',MP),
  q(NERV,'A 40-year-old has jerky, dance-like movements, mood changes and a parent who had the same illness. What is likely?','Huntington disease',['Parkinson disease','Essential tremor','Alzheimer disease, which mainly affects memory'],'B','Huntington disease is autosomal dominant and caused by an expanded CAG repeat.',CMDT),
  q(REPRO,'A 22-year-old woman has a smooth, rubbery, movable, painless breast lump. What is the most likely diagnosis?','Fibroadenoma',['Inflammatory breast cancer','Mastitis','Paget disease of the nipple'],'C','Fibroadenomas are common benign tumors in young women and are often confirmed with ultrasound.',MP),
  q(REPRO,'A 51-year-old woman has hot flashes and no period for 12 months. Which lab finding is expected?','High FSH',['Low FSH','High estrogen','High progesterone from ovulation every month'],'D','When the ovaries stop responding, the pituitary releases more FSH to try to stimulate them.',MP),
  q(URIN,'Which test best detects early kidney damage in a patient with diabetes?','Urine albumin-to-creatinine ratio',['Urine color check','Serum calcium','A kidney X-ray'],'A','Small amounts of albumin in the urine are an early sign of diabetic kidney disease.',CMDT),
  q(URIN,'A sexually active young man has burning with urination and a discharge from the penis. What is the most likely cause?','Urethritis from gonorrhea or chlamydia',['Kidney stone','Bladder cancer','Benign prostatic hyperplasia in an older man'],'B','A urine NAAT test checks for both infections, and partners also need treatment.',CMDT),
  q(MENT,'A patient started on an antidepressant and a migraine drug develops fever, agitation, sweating and muscle twitching. What is likely?','Serotonin syndrome',['Opioid withdrawal','Panic disorder','Neuroleptic malignant syndrome with slow onset'],'C','Serotonin syndrome comes on quickly after adding or raising serotonergic drugs and can be life-threatening.',CMDT),
  q(MENT,'A patient has unstable relationships, fear of abandonment, impulsive behavior and repeated self-harm. Which disorder is likely?','Borderline personality disorder',['Antisocial personality disorder','Schizophrenia','Obsessive-compulsive disorder'],'D','Dialectical behavior therapy is an effective treatment for borderline personality disorder.',MP),
  q(MENT,'Six weeks after giving birth, a mother has low mood, loss of interest and trouble bonding with her baby. Which screening tool is commonly used?','The Edinburgh Postnatal Depression Scale',['The Apgar score','The Glasgow Coma Scale','The CAGE questionnaire for alcohol use'],'A','Postpartum depression is common and treatable, and screening is recommended at well visits.',MP),
  q(ASSESS,'A patient reads the 20/40 line on a Snellen chart. What does this mean?','They see at 20 feet what a normal eye sees at 40 feet',['They see at 40 feet what a normal eye sees at 20 feet','They have perfect vision','They are legally blind'],'B','The larger the bottom number, the worse the distance vision; 20/20 is considered normal.',CMDT),
  q(ASSESS,'Pain in the right lower abdomen when the patient lifts the right thigh against resistance is called a positive:','Psoas sign',['Murphy sign','Babinski sign','Homan sign used for calf pain'],'C','The psoas sign suggests an inflamed appendix lying next to the psoas muscle.',CMDT),
  q(ASSESS,'Where is the point of maximal impulse (PMI) of the heart normally felt?','At the fifth intercostal space, midclavicular line',['At the second intercostal space, right sternal border','At the xiphoid process','In the left armpit'],'D','A PMI moved to the left and down may suggest an enlarged heart.',CMDT),
  q(ASSESS,'A patient with heart failure has an extra low-pitched sound right after S2. What is it?','An S3 gallop',['An S1 split','A pericardial knock from surgery','A carotid bruit heard over the neck'],'A','An S3 suggests a stiff or overfilled ventricle and is common in heart failure.',CMDT),
  q(ASSESS,'A murmur is loud and has a palpable thrill. What is its lowest possible grade?','Grade 4 of 6',['Grade 1 of 6','Grade 2 of 6','Grade 6 of 6 only'],'B','Murmurs of grade 4 and above have a thrill, and grade 6 can be heard with the stethoscope off the chest.',CMDT),
  q(ASSESS,'A patient correctly states their name, location, the date and what is happening. How is this recorded?','Alert and oriented × 4',['Confused','Disoriented to time','Alert and oriented × 1'],'C','Orientation to person, place, time and situation is a quick check of mental status.',CMDT),
  q(DX,'Spirometry after a bronchodilator shows an FEV1/FVC ratio below 0.70 that does not fully reverse. What does this support?','Chronic obstructive pulmonary disease (COPD)',['Restrictive lung disease','Normal lungs','Asthma that has fully reversed with treatment'],'D','A fixed low FEV1/FVC ratio confirms airflow limitation that does not fully reverse.',CMDT),
  q(DX,'A 72-year-old has a new headache, jaw pain when chewing and a very high ESR. Which test confirms the suspected diagnosis?','Temporal artery biopsy',['Lumbar puncture','Brain MRI with contrast','Carotid ultrasound to look for plaque'],'A','Giant cell arteritis can cause blindness, so steroids are started right away while the biopsy is arranged.',CMDT),
  q(DX,'Which imaging test is usually first for suspected gallstones?','Abdominal ultrasound',['Chest X-ray','Head CT','Bone scan'],'B','Ultrasound shows gallstones well without radiation and can show gallbladder wall thickening.',CMDT),
  q(DX,'Which test confirms sickle cell disease by showing the types of hemoglobin present?','Hemoglobin electrophoresis',['Complete metabolic panel','Urinalysis','Blood culture'],'C','Electrophoresis separates hemoglobin types, such as HbS and HbA, by their charge.',CMDT),
  q(DX,'Under 2024 USPSTF guidance, when should average-risk women begin screening mammograms?','At age 40, every 2 years',['At age 18','At age 65 only','At age 30, every year'],'D','Screening continues every 2 years through age 74 for women at average risk.',CMDT),
  q(DX,'A woman has burning with urination and frequency. Which urine dipstick result most suggests a bacterial infection?','Positive nitrite',['Positive ketones','Positive bilirubin','High specific gravity from mild dehydration'],'A','Many gram-negative bacteria, such as E. coli, convert urinary nitrate to nitrite.',CMDT),
  q(DX,'Which HIV test can detect infection earlier by finding both p24 antigen and antibodies?','A fourth-generation antigen/antibody test',['A Western blot only','A CD4 count','A viral culture of saliva'],'B','Detecting p24 antigen shortens the window period before antibodies appear.',CMDT)
 ],9631)
};
